<?php recoveryUiSteps(['Select inventory','Sales Order','Review & Confirm','Complete']); recoveryUiSelection($flowDevices,($_GET['operation']??'')==='harvest'?'REC_HARVEST':'REC_WHOLESALE'); ?><section class="card workflow-card"><h2>Confirm serialized transaction</h2><form id="exit" class="workflow-form"><label>Action <select id="operation"><option value="sales-handoff">Allocate Wholesale to existing Draft Sales Order</option><option value="wholesale">Confirm Wholesale serial scan-out after ERP fulfillment</option><option value="harvest">Complete internal Harvest</option></select></label>
<label>Scan serial <input id="serial" required autocomplete="off"></label>
<div id="sales"><label>ERP Sales Order ID <input id="order" type="number" min="1"></label><p>Allocation requires a Draft order. Exit requires a Completed order with this serial in its outbound container and a recorded sale price.</p></div>
<div id="harvest" hidden><label>Scan current Harvest location <input id="location" autocomplete="off"></label><label>Final disposition <textarea id="disposition" maxlength="500" placeholder="Parts harvested / final disposition"></textarea></label></div>
<div id="economics" hidden><label>Confirmed direct costs (USD) <input id="costs" type="number" min="0" step="0.01" placeholder="Enter 0 if none"></label><p>Gross comes from the ERP serial sale price. Net equals gross minus these confirmed costs. This connector currently records USD outcomes.</p></div><button class="btn-primary" id="submit">Commit serialized transaction</button></form></section><p id="message" role="status"></p><p><a href="/pages/analysis-detail.php">Analyze outcomes</a> · <a href="/pages/disposition.php">Disposition inventory</a></p></div></div></main>
<script src="/assets/js/workflow-selection.js"></script>
<script>
const operation=document.getElementById('operation');operation.onchange=()=>{const harvest=operation.value==='harvest';document.getElementById('harvest').hidden=!harvest;document.getElementById('sales').hidden=harvest;document.getElementById('economics').hidden=operation.value!=='wholesale';};
document.getElementById('exit').onsubmit=async e=>{e.preventDefault();const button=document.getElementById('submit');button.disabled=true;try{const response=await fetch('/api/disposition/execute.php',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({operation:operation.value,currency:'USD',direct_costs:document.getElementById('costs').value,serial_number:document.getElementById('serial').value,sales_order_id:document.getElementById('order').value,location_scan:document.getElementById('location').value,final_disposition:document.getElementById('disposition').value})});const data=await response.json();if(!response.ok||!data.success)throw new Error(data.message||'ERP did not confirm the transaction.');document.getElementById('message').textContent=data.serial_number+' · '+data.status+' · ERP receipt '+data.request_key;}catch(e){document.getElementById('message').textContent=e.message;}finally{button.disabled=false;}};
</script><script src="/assets/js/reference-transactions.js"></script></body></html>
